mapper.select:
SELECT 
FROM marketing_task_export_job
WHERE id = #{id}
  AND created_by = #{createdBy}
  AND export_mode IN ('RECIPIENTS', 'ACCOUNT_STATS', 'ATTRIBUTION', 'VISIT_TREND')

SELECT 
FROM marketing_task_export_job
WHERE tenant_id = #{tenantId}
  AND created_by = #{createdBy}
  AND request_hash = #{requestHash}
  AND export_mode = 'RECIPIENTS'
  AND status IN ('PENDING', 'PROCESSING')
ORDER BY id DESC
LIMIT 1

mapper.update:
UPDATE marketing_task_export_job
SET lease_until = #{leaseUntil}, updated_at = #{now}
WHERE tenant_id = #{tenantId} AND id = #{id} AND export_mode = 'RECIPIENTS'
  AND status = 'PROCESSING' AND claim_token = #{claimToken}

UPDATE marketing_task_export_job
SET status = 'FAILED', error_message = #{errorMessage}, lease_until = NULL,
    claim_token = NULL, finished_at = #{finishedAt}, updated_at = #{finishedAt}
WHERE tenant_id = #{tenantId} AND id = #{id} AND export_mode = 'RECIPIENTS'
  AND status = 'PROCESSING' AND claim_token = #{claimToken}

UPDATE marketing_task_export_job
SET storage_key = NULL, content_type = NULL, file_size = NULL, updated_at = #{now}
WHERE tenant_id = #{tenantId} AND id = #{id} AND export_mode = 'RECIPIENTS'
  AND status = 'SUCCESS' AND storage_key = #{storageKey} AND expires_at <= #{now}
